head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > P > dateSuffix]<br/>일 컬럼에 표시되는 숫자 뒤에 추가할 접미사를 설정합니다.",
    "validation" : [
        "일 컬럼에 표시되는 숫자 뒤에 추가할 접미사를 설정합니다.",
        "String 값으로 일 숫자 뒤에 표시할 문자열을 설정합니다.",
        "값을 설정하지 않으면 '일'이 설정됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let dateSuffixValue = par_dateSuffix.getText();

    let properties = {};

    // '미설정' 선택 시 properties 에 추가하지 않아 엔진 기본값 '일' 적용 확인
    if (dateSuffixValue !== "" && dateSuffixValue !== "미설정") {
        properties.dateSuffix = dateSuffixValue;
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicDatePicker(cList);
}



// 일 컬럼 itemArr 라벨 출력 (1번째, 15번째, 마지막)
scwin.getDateSuffixInfo = function () {
    // 일 컬럼 존재 여부 확인 (calendarValueType 에 'date' 가 포함되어야 일 컬럼 존재)
    if (!target1.colTypeObj || !target1.colTypeObj.hasOwnProperty('date')) {
        wf_body_bottom.getObj("scwin").setReturnValue("[일 컬럼 적용] 일 컬럼이 존재하지 않아 dateSuffix 가 적용되지 않음");
        return;
    }

    let dateIdx = target1.colTypeObj['date'];
    let dateCol = target1.childControlList[dateIdx];

    if (!dateCol || !dateCol.itemArr || dateCol.itemArr.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[일 컬럼 라벨] 컬럼 정보 없음");
        return;
    }

    // itemArr[0] = 1일, itemArr[14] = 15일 (j + dateSuffix 형태로 addItem)
    let firstLabel = dateCol.itemArr[0].label;
    let midLabel = dateCol.itemArr[14].label;
    let lastLabel = dateCol.itemArr[dateCol.itemArr.length - 1].label;

    // validation: 일 숫자 뒤에 접미사가 붙어 표시됨
    wf_body_bottom.getObj("scwin").setReturnValue("[일 컬럼 라벨 itemArr] 1번째='" + firstLabel + "' / 15번째='" + midLabel + "' / 마지막='" + lastLabel + "'");
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getDateSuffixInfo();
}
